MOD = 10**9 + 7

def count_similar_permutations(n, a):
    # Initialize the DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            dp[i][j] = dp[i - 1][j] * max(0, j - (i - 1)) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

    result = 0
    for j in range(n + 1):
        result = (result + dp[n][j]) % MOD

    return result

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        results.append(count_similar_permutations(n, a))

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
